// A field holding a value of a schema or a list of them: how a form holds
// every value as text under the path to it, a field by its name, a part of
// a value as address.street, a part of a list's item as phones.0.number,
// with the number of items under phones#items.

import { fieldProblem, typed } from "./rules.js";
import { say } from "./texts.js";

/** Whether a field holds a value of a schema or a list of them. */
export function holdsValue(field) {
  return field.type === "value" || field.type === "valueList";
}

/** The key a list keeps its number of items under. */
export function itemsOf(path) {
  return path + "#items";
}

/** The number of items a list at path holds. */
export function countOf(values, path) {
  return Number(values[itemsOf(path)] ?? "0");
}

function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * The text a field starts with from what the record holds, written into
 * out by path: a value part by part, a list item by item, or on a form
 * that creates one as many empty items as its minimum.
 */
export function startValue(field, held, path, out) {
  switch (field.type) {
    case "value": {
      const value = isRecord(held) ? held : {};
      for (const part of field.parts) {
        startValue(part, value[part.name], path + "." + part.name, out);
      }
      return;
    }
    case "valueList": {
      const items = Array.isArray(held) ? held : undefined;
      const count = items?.length ?? field.minimum ?? 0;
      out[itemsOf(path)] = String(count);
      for (let index = 0; index < count; index++) {
        const item = items?.[index];
        for (const part of field.parts) {
          startValue(part, isRecord(item) ? item[part.name] : undefined, path + "." + index + "." + part.name, out);
        }
      }
      return;
    }
    case "checkbox":
      out[path] = String(held ?? false);
      return;
    default:
      out[path] = held === null || held === undefined ? "" : String(held);
  }
}

/** Whether a person gave any part of the value at path: a text typed, a box ticked or an item added. */
export function given(field, values, path) {
  switch (field.type) {
    case "value":
      return field.parts.some((part) => given(part, values, path + "." + part.name));
    case "valueList":
      return countOf(values, path) > 0;
    case "checkbox":
      return values[path] === "true";
    default:
      return (values[path] ?? "") !== "";
  }
}

/**
 * A field's value as the service takes it: a value as an object of the
 * parts given, null while an optional one has none; a list as an array of
 * its items; anything else typed as the field is.
 */
export function sentValue(field, values, path) {
  switch (field.type) {
    case "value":
      if (!field.required && !given(field, values, path)) {
        return null;
      }
      return partsSent(field.parts, values, path);
    case "valueList":
      return Array.from({ length: countOf(values, path) }, (_, index) => partsSent(field.parts, values, path + "." + index));
    default:
      return typed(field, values[path] ?? "");
  }
}

function partsSent(parts, values, path) {
  const value = {};
  for (const part of parts) {
    const sent = sentValue(part, values, path + "." + part.name);
    if (sent !== null) {
      value[part.name] = sent;
    }
  }
  return value;
}

/**
 * What stops a value being sent, by path: each part by its keywords, its
 * required parts once an optional value has one given, and a list's
 * number of items.
 */
export function valueProblems(field, values, path, texts, problems) {
  switch (field.type) {
    case "value":
      if (field.required || given(field, values, path)) {
        for (const part of field.parts) {
          valueProblems(part, values, path + "." + part.name, texts, problems);
        }
      }
      return;
    case "valueList": {
      const count = countOf(values, path);
      if (field.minimum !== undefined && count < field.minimum) {
        problems[path] = say(texts, { text: "screens.itemsAtLeast", count: field.minimum });
      } else if (field.maximum !== undefined && count > field.maximum) {
        problems[path] = say(texts, { text: "screens.itemsAtMost", count: field.maximum });
      }
      for (let index = 0; index < count; index++) {
        for (const part of field.parts) {
          valueProblems(part, values, path + "." + index + "." + part.name, texts, problems);
        }
      }
      return;
    }
    default: {
      if (field.readOnly === true) {
        return;
      }
      const problem = fieldProblem(field, values[path] ?? "", texts);
      if (problem !== undefined) {
        problems[path] = problem;
      }
    }
  }
}

/** The values with an empty item added at the end of the list at path. */
export function addItem(field, values, path) {
  const count = countOf(values, path);
  const next = { ...values, [itemsOf(path)]: String(count + 1) };
  for (const part of field.parts) {
    startValue(part, undefined, path + "." + count + "." + part.name, next);
  }
  return next;
}

/** The values with the item at index taken out of the list at path, the later items moved up. */
export function removeItem(values, path, index) {
  const prefix = path + ".";
  const next = {};
  for (const [key, value] of Object.entries(values)) {
    const at = key.startsWith(prefix) ? /^(\d+)([.#].*)$/.exec(key.slice(prefix.length)) : null;
    if (at === null) {
      next[key] = value;
      continue;
    }
    const item = Number(at[1]);
    if (item !== index) {
      next[prefix + (item > index ? item - 1 : item) + at[2]] = value;
    }
  }
  next[itemsOf(path)] = String(Math.max(0, countOf(values, path) - 1));
  return next;
}

/** The first path under a field that has a problem, to focus; undefined when none has. */
export function firstProblem(field, problems) {
  return Object.keys(problems).find((key) => key === field.name || key.startsWith(field.name + ".") || key.startsWith(field.name + "#"));
}

/** The scalar fields of a list of form fields. */
export function scalars(fields) {
  return fields.filter((field) => !holdsValue(field));
}
